files.content:
[hidden] { display: none !important; }

:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --accent-hover: #ff6b81;
  --text: #eaeaea;
  --muted: #a0a0b0;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: 'Courier New', Courier, monospace;
  font-size: 18px;
  color: var(--text);
  padding: 16px;
}

.quiz-card {
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 0;
  padding: 32px 24px;
  width: 100%;
  max-width: 420px;
  text-align: center;
  box-shadow: 8px 8px 0 rgba(0,0,0,0.4);
}

.quiz-title {
  font-size: 1.6rem;
  letter-spacing: 2px;
  margin-bottom: 24px;
  color: var(--accent);
  text-transform: uppercase;
}

.question {
  font-size: 1.5rem;
  margin-bottom: 24px;
  min-height: 2.2rem;
  letter-spacing: 1px;
}

.answers {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-bottom: 24px;
  flex-wrap: wrap;
}

.answer-btn, .control-btn {
  font-family: inherit;
  font-size: 1.1rem;
  padding: 12px 24px;
  border: 3px solid var(--accent);
  border-radius: 0;
  background: transparent;
  color: var(--text);
  cursor: pointer;
  transition: background 0.1s, transform 0.05s;
  min-width: 80px;
}

.answer-btn:hover, .control-btn:hover {
  background: var(--accent-hover);
  color: var(--bg);
}

.answer-btn:focus-visible, .control-btn:focus-visible {
  outline: 3px solid var(--accent-hover);
  outline-offset: 3px;
}

.answer-btn:active, .control-btn:active {
  transform: translate(2px, 2px);
}

.answer-btn:disabled, .control-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  transform: none;
}

.answer-btn:disabled:hover, .control-btn:disabled:hover {
  background: transparent;
  color: var(--text);
}

.score-line {
  font-size: 1.2rem;
  margin-bottom: 24px;
  color: var(--muted);
}

#score { color: var(--accent); font-weight: bold; }

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

@media (max-width: 400px) {
  .quiz-card { padding: 24px 16px; }
  .quiz-title { font-size: 1.3rem; }
  .question { font-size: 1.3rem; }
  .answer-btn, .control-btn { font-size: 1rem; padding: 10px 18px; }
}

const questionEl = document.getElementById('question');
const answerA = document.getElementById('answer-a');
const answerB = document.getElementById('answer-b');
const scoreEl = document.getElementById('score');
const nextBtn = document.getElementById('next');
const restartBtn = document.getElementById('restart');

const QUESTIONS = [
  { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
  { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
];

let currentIndex = 0;
let score = 0;
let answered = false;

function render() {
  if (currentIndex >= QUESTIONS.length) {
    questionEl.textContent = 'Finished';
    answerA.disabled = true;
    answerB.disabled = true;
    nextBtn.disabled = true;
    return;
  }
  const q = QUESTIONS[currentIndex];
  questionEl.textContent = q.text;
  answerA.textContent = q.a;
  answerB.textContent = q.b;
  answerA.disabled = false;
  answerB.disabled = false;
  nextBtn.disabled = true;
  answered = false;
}

function handleAnswer(choice) {
  if (answered || currentIndex >= QUESTIONS.length) return;
  answered = true;
  answerA.disabled = true;
  answerB.disabled = true;
  if (choice === QUESTIONS[currentIndex].correct) {
    score++;
    scoreEl.textContent = score;
  }
  nextBtn.disabled = false;
}

answerA.addEventListener('click', () => handleAnswer('a'));
answerB.addEventListener('click', () => handleAnswer('b'));

nextBtn.addEventListener('click', () => {
  if (currentIndex < QUESTIONS.length) {
    currentIndex++;
    render();
  }
});

restartBtn.addEventListener('click', () => {
  currentIndex = 0;
  score = 0;
  scoreEl.textContent = score;
  render();
});

render();
